                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int[] heights = new int[n];

        for (int i = 0; i < n; i++) {
            heights[i] = fs.nextInt();
        }

        long[] events = new long[2 * n];
        int eventCount = 0;

        // The first rectangle starts a run for every cut below its height.
