                events[eventCount++] = 2L * heights[i - 1] + 1; // Start
                events[eventCount++] = 2L * heights[i]; // End
            }
        }

        Arrays.sort(events, 0, eventCount);

        int active = 0;
        int maxRuns = 0;

        for (int i = 0; i < eventCount; i++) {
            if ((events[i] & 1L) == 1L) {
                active++;
                maxRuns = Math.max(maxRuns, active);
            } else {
                active--;
            }
        }

        System.out.println(maxRuns + 1);
    }
